import type { SkImage } from '@shopify/react-native-skia';
import { spriteSet } from './spriteSet';

/** Generated by scripts/extract_ship_sprites.py: straight ships point right, shaped ships use rotation 0. */
const sprites = spriteSet({
  carrier: require('../../assets/images/ships/carrier.png'),
  battleship: require('../../assets/images/ships/battleship.png'),
  cruiser: require('../../assets/images/ships/cruiser.png'),
  submarine: require('../../assets/images/ships/submarine.png'),
  destroyer: require('../../assets/images/ships/destroyer.png'),
  tfrigate: require('../../assets/images/ships/tfrigate.png'),
  lcorvette: require('../../assets/images/ships/lcorvette.png'),
  zraider: require('../../assets/images/ships/zraider.png'),
});

type SpriteId = Parameters<typeof sprites.get>[0];

const ALIASES: Record<string, SpriteId> = { dreadnought: 'battleship' };

/** Decodes all ship sprites once. Ship art is rasterized into cached icons, so this must finish before first draw. */
export const loadShipSprites = () => sprites.load();

/** Null when image graphics are off or the class has no sprite, so the hull is drawn procedurally. */
export function shipSprite(defId: string): SkImage | null {
  return sprites.get((ALIASES[defId] ?? defId) as SpriteId);
}
